import math

def phi(n):
    result = n
    p = 2
    while p * p <= n:
        if n % p == 0:
            while n % p == 0:
                n //= p
            result -= result // p
        p += 1
    if n > 1:
        result -= result // n
    return result

def order(a, n):
    if math.gcd(a, n) != 1:
        return -1
    res = 1
    curr = a % n
    while curr != 1:
        curr = (curr * a) % n
        res += 1
    return res

